import {allProvidersList, type Provider} from './config'
import {createContext, type PropsWithChildren, use} from 'react'
import invariant from 'tiny-invariant'

const ProvidersContext = createContext<Provider[]>([])

const allProviderKeys = allProvidersList.map(p => p.key)

export function ProvidersProvider({children, providers}: PropsWithChildren<{providers: Provider[]}>) {
  const providerKeys = providers.filter(p => allProviderKeys.includes(p))
  invariant(providerKeys.length > 0, 'ProvidersProvider requires at least one valid provider')
  return <ProvidersContext value={providerKeys}>{children}</ProvidersContext>
}

export function useProviders() {
  const providers = use(ProvidersContext)
  invariant(providers.length > 0, 'useProviders must be used within a ProvidersProvider')
  return providers
}
