import type {Provider} from '@github-ui/copilot-byok/providers'

// Keep in sync with endpoint_type enum in packages/copilot_byok/app/models/copilot_byok/custom_model_capability.rb in github/github
export const EndpointType = {
  ChatCompletions: 'chat_completions',
  Responses: 'responses',
} as const

export type EndpointType = (typeof EndpointType)[keyof typeof EndpointType]

// Keep in sync with `CustomModelsIndexPayload` in app/controllers/orgs/copilot_settings/byok_custom_models_controller.rb in github/github
export interface CustomModelsIndexPayload {
  publicKey: [version: number, base64EncodedKey: string]
  orgDisplayLogin: string
  customKeys: CustomKey[]
  customModels: CustomModel[]
  enabled: boolean
  business?: {
    name: string
    slug: string
  }
  availableProviders: Provider[]
}

export type CustomModelsIndexTabs = 'keys' | 'models'

export interface CreateCustomKeyMutationData {
  name: string
}

// Keep in sync with `SelectorCustomModel` in packages/copilot_byok/app/public/copilot_byok/types.rb in github/github
export type SelectorCustomModel = {
  slug: string
  name?: string
  deprecated?: boolean
  fresh?: boolean
  createdAt?: number
  id?: number
  selected?: boolean
  maxOutputTokens?: number
  additionalData?: Record<string, unknown>
}

export type ProviderAdditionalData = {models?: SelectorCustomModel[]} | undefined

// Keep in sync with `CustomModel` in packages/copilot_byok/app/public/copilot_byok/types.rb
// in github/github
export type CustomModel = {
  id: number
  slug: string
  name?: string
  customKeyId: CustomKey['id']
  /**
   * Whether this custom model can be configured and enabled or disabled by the authenticated user in the context
   * where it's being rendered.
   */
  editable?: boolean
  enabled: boolean
  toolCalling?: boolean
  vision?: boolean
  thinking?: boolean
  maxInputTokens?: number
  maxOutputTokens?: number
  streaming?: boolean
  endpointType?: EndpointType
  maxContextWindow?: number
}

// Keep in sync with `CustomKey` in packages/copilot_byok/app/public/copilot_byok/types.rb
export type CustomKey = {
  id: number
  name: string
  totalModels: number
  /**
   * Whether this custom key can be modified by the authenticated user in the context where it's being rendered.
   */
  editable?: boolean
  /**
   * Display name of the owner of this custom key. Not suitable for use in URL construction.
   */
  ownerName: string
} & ProviderData

export type ProviderData =
  | {provider: 'azureai'; deploymentUrl: string}
  | {provider: 'awsbedrock'; accessKey?: string | null; region: string}
  | {provider: 'openai'}
  | {provider: 'openaicompatible'; baseUrl: string}
  | {provider: 'anthropic'}
  | {provider: 'xai'}
  | {provider: 'googleaistudio'}

export type ProviderDataFor<P extends Provider> = Extract<ProviderData, {provider: P}>

interface CustomModelConfig {
  name?: string | null
  toolCalling?: boolean
  vision?: boolean
  thinking?: boolean
  maxInputTokens?: number
  maxOutputTokens?: number
}

/**
 * Common fields used for updating any custom key, whether enterprise- or organization-owned.
 */
export type UpdateCustomKeyPayload = {
  name?: string
  api_key?: string | null
  access_key?: string | null // AWS Bedrock
  provider_data?: Record<string, unknown> // Provider-specific data (e.g., Microsoft Foundry, OpenAI Compatible, AWS Bedrock)
  models?: Array<
    | ({
        slug: string
      } & CustomModelConfig)
    | ({
        id: number
      } & CustomModelConfig)
  >
}
